namespace sv_fca241ee35324800b952277855ff2eaf.Services;

public class AppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        var doctors = new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Patel",
            "Dr. Lee",
            "Dr. Garcia"
        };
        return Task.FromResult(doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateTime date)
    {
        var slots = new List<string>
        {
            "9:00 AM",
            "10:00 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM",
            "4:00 PM"
        };
        return Task.FromResult(slots);
    }

    public Task<ValidationResult> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var result = new ValidationResult();

        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.FieldErrors["Email"] = "Account has outstanding balance";
        }

        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            result.FieldErrors["Doctor"] = "Selected doctor does not accept self-pay patients";
        }

        if (timeSlot == "10:00 AM")
        {
            result.FieldErrors["TimeSlot"] = "This slot is no longer available";
        }

        return Task.FromResult(result);
    }
}

public class ValidationResult
{
    public Dictionary<string, string> FieldErrors { get; set; } = new();
    public bool IsValid => FieldErrors.Count == 0;
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_fca241ee35324800b952277855ff2eaf.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    <h3>Step 1: Patient Information</h3>

    <div class="mb-3">
        <label class="form-label" for="patientName">Patient Name</label>
        <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
        <ValidationMessage For="() => Model.PatientName" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="email">Email</label>
        <InputText id="email" class="form-control" @bind-Value="Model.Email" />
        <ValidationMessage For="() => Model.Email" />
        @if (!string.IsNullOrEmpty(serverErrors.GetValueOrDefault("Email")))
        {
            <div class="validation-message">@serverErrors["Email"]</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label" for="phone">Phone</label>
        <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
        <ValidationMessage For="() => Model.Phone" />
    </div>

    <div class="mb-3">
        <label class="form-label" for="insurance">Insurance Provider</label>
        <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
            <option value="">-- Select --</option>
            <option value="Aetna">Aetna</option>
            <option value="BlueCross">BlueCross</option>
            <option value="Cigna">Cigna</option>
            <option value="UnitedHealth">UnitedHealth</option>
            <option value="None">None</option>
        </InputSelect>
        <ValidationMessage For="() => Model.InsuranceProvider" />
    </div>

    @if (!showStep2)
    {
        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">Next</button>
    }

    @if (showStep2)
    {
        <hr />
        <h3>Step 2: Appointment Details</h3>

        <div class="mb-3">
            <label class="form-label" for="doctor">Preferred Doctor</label>
            <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor" ValueChanged="OnDoctorChanged" ValueExpression="() => Model.Doctor">
                <option value="">-- Select --</option>
                @foreach (var doc in doctors)
                {
                    <option value="@doc">@doc</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.Doctor" />
            @if (!string.IsNullOrEmpty(serverErrors.GetValueOrDefault("Doctor")))
            {
                <div class="validation-message">@serverErrors["Doctor"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="date">Date</label>
            <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate" />
            <ValidationMessage For="() => Model.AppointmentDate" />
            @if (Model.AppointmentDate.HasValue && Model.AppointmentDate.Value <= DateTime.Today)
            {
                <div class="validation-message">Date must be in the future</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="timeSlot">Time Slot</label>
            <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                <option value="">-- Select --</option>
                @foreach (var slot in timeSlots)
                {
                    <option value="@slot">@slot</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.TimeSlot" />
            @if (!string.IsNullOrEmpty(serverErrors.GetValueOrDefault("TimeSlot")))
            {
                <div class="validation-message">@serverErrors["TimeSlot"]</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="reason">Reason for Visit</label>
            <InputTextArea id="reason" class="form-control" @bind-Value="Model.ReasonForVisit" rows="4" />
            <ValidationMessage For="() => Model.ReasonForVisit" />
        </div>

        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability" disabled="@isChecking">
            @(isChecking ? "Checking..." : "Check Availability")
        </button>
        <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed)">Book Appointment</button>

        @if (availabilityConfirmed)
        {
            <div class="alert alert-success mt-3">Availability confirmed! Click "Book Appointment" to finalize.</div>
        }
    }
</EditForm>

@if (appointmentBooked)
{
    <div class="alert alert-success mt-4">
        <strong>Appointment booked successfully!</strong> A confirmation has been sent to @Model.Email.
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private List<string> doctors = new();
    private List<string> timeSlots = new();
    private Dictionary<string, string> serverErrors = new();
    private bool showStep2;
    private bool isChecking;
    private bool availabilityConfirmed;
    private bool appointmentBooked;
    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        editContext = new EditContext(Model);
        var isStep1Valid = !string.IsNullOrWhiteSpace(Model.PatientName)
            && !string.IsNullOrWhiteSpace(Model.Email)
            && IsValidEmail(Model.Email)
            && !string.IsNullOrWhiteSpace(Model.Phone)
            && !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (isStep1Valid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorChanged(string value)
    {
        Model.Doctor = value;
        serverErrors.Remove("Doctor");
        availabilityConfirmed = false;

        if (!string.IsNullOrEmpty(value) && Model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(value, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityConfirmed = false;

        if (string.IsNullOrWhiteSpace(Model.Doctor)
            || !Model.AppointmentDate.HasValue
            || Model.AppointmentDate.Value <= DateTime.Today
            || string.IsNullOrWhiteSpace(Model.TimeSlot)
            || string.IsNullOrWhiteSpace(Model.ReasonForVisit)
            || Model.ReasonForVisit.Length > 500)
        {
            return;
        }

        isChecking = true;
        StateHasChanged();

        try
        {
            var result = await AppointmentService.ValidatePatientAsync(
                Model.Email,
                Model.InsuranceProvider,
                Model.Doctor,
                Model.TimeSlot);

            if (result.IsValid)
            {
                availabilityConfirmed = true;
            }
            else
            {
                serverErrors = new Dictionary<string, string>(result.FieldErrors);
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityConfirmed)
        {
            appointmentBooked = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}

