    protected override async Task OnInitializedAsync()
    {
        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        editContext = new EditContext(Model);
        var isStep1Valid = !string.IsNullOrWhiteSpace(Model.PatientName)
            && !string.IsNullOrWhiteSpace(Model.Email)
            && IsValidEmail(Model.Email)
            && !string.IsNullOrWhiteSpace(Model.Phone)
            && !string.IsNullOrWhiteSpace(Model.InsuranceProvider);

        if (isStep1Valid)
        {
            showStep2 = true;
        }
    }

    private async Task OnDoctorChanged(string value)
    {
        Model.Doctor = value;
        serverErrors.Remove("Doctor");
        availabilityConfirmed = false;

        if (!string.IsNullOrEmpty(value) && Model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(value, Model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityConfirmed = false;

        if (string.IsNullOrWhiteSpace(Model.Doctor)
            || !Model.AppointmentDate.HasValue
            || Model.AppointmentDate.Value <= DateTime.Today
            || string.IsNullOrWhiteSpace(Model.TimeSlot)
            || string.IsNullOrWhiteSpace(Model.ReasonForVisit)
            || Model.ReasonForVisit.Length > 500)
        {
            return;
        }

        isChecking = true;
        StateHasChanged();

        try
        {
            var result = await AppointmentService.ValidatePatientAsync(
                Model.Email,
                Model.InsuranceProvider,
                Model.Doctor,
                Model.TimeSlot);

            if (result.IsValid)
            {
                availabilityConfirmed = true;
            }
            else
            {
                serverErrors = new Dictionary<string, string>(result.FieldErrors);
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (availabilityConfirmed)
        {
            appointmentBooked = true;
        }
    }

    private static bool IsValidEmail(string email)
    {
        try
        {
            var addr = new System.Net.Mail.MailAddress(email);
            return addr.Address == email;
        }
        catch
        {
            return false;
        }
    }
}
"}

